void blacklist_find_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_blacklist_find_obj_t * p_screen_param;
    lv_obj_t *      list;
    uint32_t        child_cnt;
    uint32_t        child_id;
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;

    p_screen_param      = (ui_screen_blacklist_find_obj_t *) lv_obj_get_user_data(ui_Screen);

    list                = get_blacklist_find_list_obj(ui_Screen);

    if (list) {
        child_cnt           = lv_obj_get_child_cnt(list);
        child_id            = get_list_child_focused_id(list,child_cnt);
        }
    else {
        child_cnt           = 0;
        child_id            = 0;

        }

    __inf("blacklist_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);

    switch (key)
    {
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,0);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,0);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

        case LV_KEY_ENTER:
        case APP_KEY_VALUE_TOP_LEFT:
            {
                phonebook_param_t phonebook_param;
                phonebook_map_node_t * p_cur_node;

                if (list == NULL)
                    break;

                get_focus_obj       = lv_obj_get_child(list,child_id);
                p_cur_node          = (phonebook_map_node_t *) lv_obj_get_user_data(get_focus_obj);

                if (p_cur_node) {
                    read_phonebook_param_storge(p_cur_node,&phonebook_param);
                    strncpy(p_screen_param->enter_param.p_number,phonebook_param.number,
                        p_screen_param->enter_param.number_size);

                    }

                alv_am_win_exit_current(NULL);
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);

                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}



